"""Explain pointer clearing, dummy isolation and metadata address translation."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1745': ('공책에 붙인 두 안내 화살표를 지우는 일과 공책 내용을 지우는 일은 달라요. 화살표가 없어져도 공책의 글자는 그대로일 수 있어요.', '메타데이터 연결 제거와 내용 초기화·메모리 해제를 구별합니다.', '페이지P의 shadow연결S·origin연결O를 NULL·NULL로 바꾸고,내용42는 그대로인 그림을 그리세요.', ['page는 커널이 메모리 페이지를 관리하는 자료구조예요. 그 안의 kmsan_shadow와 kmsan_origin은 준비 상태표와 원인표의 페이지를 가리키는 연결이에요. 포인터는 연결된 위치를 나타내는 값이에요.', 'set_no_shadow_origin_page의 본문은 이 두 연결에 각각NULL을 대입해요. NULL은 연결된 대상이 없다는 특별한 포인터 값이에요. shadow_page_for와 origin_page_for는 해당 필드를 가리키는 매크로예요.', '예를 들어 페이지P의 내용에42가 있고 검사표S와 원인표O로 연결되어 있다고 해 봐요. 이 함수를 부르면 두 연결은NULL이 돼요. 하지만 본문에는 내용42를0으로 바꾸는 memset이 없어요. 연결 필드의 변경과 페이지 내용의 변경은 달라요.', '페이지를 해제하는 함수 호출도 없어요. 따라서 이 함수만 보고 페이지가 메모리 할당기에 반납됐다고 말할 수 없어요. 연결을 지우는 일과 저장 공간의 수명을 끝내는 일은 별도로 처리해야 해요.', '이 함수는 검사 정보 페이지를 설정하는 경로에서 쓰여요. 실제 데이터를 추적하기 위한 검사표 페이지 자체에 또 검사표를 계속 붙이면 추적용 저장 공간이 재귀적으로 늘 수 있어요. 그래서 그 페이지에는 두 검사 연결이 없다고 표시해요.', '이것이 원래 데이터의 모든 poison 상태를 지운다는 뜻도 아니에요. 어느 page를 인자로 받았는지와 정확히 어떤 필드에 대입하는지 확인하세요. 원문의 두 줄만으로 바뀌는 상태를 먼저 좁혀 읽는 연습이에요.'], [('이 helper가 직접 바꾸는 것은 무엇인가요?', ['페이지 내용의 모든 바이트예요', '페이지의 두 메타데이터 연결 포인터예요'], '정답은 두 번째예요. 본문은 두 연결 필드에NULL을 대입해요. 실제 내용 채우기나 페이지 해제 명령은 없어요.'), ('검사 정보 페이지를 다시 끝없이 추적하도록 연결하나요?', ['아니요. 두 검사 연결이 없는 상태로 둬요', '네. 검사표마다 새 검사표를 무한히 붙여요'], '정답은 첫 번째예요. setup에서 검사 정보 페이지의 연결을NULL로 만들어요. 검사 대상 데이터와 도구 자체 저장 공간의 역할을 구별하는 처리예요.')]), 'os1746': ('쓰기용 연습장과 읽기용 빈 공책을 따로 두어요. 연습장에FF를 적어도 빈 공책의0은 그대로예요. 하지만 같은 요청에서 돌려주는 두 화살표는 같은 공책을 가리킬 수 있어요.', '반환 쌍 안의 주소 공유와 읽기·쓰기 공간 분리를 구별합니다.', 'store요청의 shadow·origin→S,load요청의 shadow·origin→L을 그리고 S와L이 다른 페이지임을 적으세요.', ['실제 검사 정보가 없을 때 dummy라는 대체 공간을 사용해요. dummy_load_page와 dummy_store_page는 각각PAGE_SIZE 바이트 배열이에요. 시작 주소도 페이지 크기 경계에 맞춰 놓도록 선언돼 있어요.', '읽기 요청의 대체 경로에서는 ret.shadow와 ret.origin이 모두dummy_load_page를 가리켜요. 즉 반환값 두 필드가 있어도 이 경우 서로 다른 페이지를 새로 하나씩 만드는 것이 아니에요. 같은 읽기 대체 페이지를 공유해요.', '쓰기 요청의 대체 경로도 두 필드가 모두dummy_store_page를 가리켜요. 다만 쓰기 대체 페이지와 읽기 대체 페이지는 별개예요. 한 요청 안의 두 포인터가 같다는 것과 load·store 전체가 같은 공간이라는 주장을 구별하세요.', '예를 들어 쓰기용 페이지의 첫 바이트를FF로 바꿔도 읽기용 페이지의 첫 바이트0은 그대로예요. 분리하지 않으면 관계없는 미추적 쓰기가 뒤의 읽기 검사 상태까지 바꿀 수 있어요. 별도 공간은 이런 간섭을 피하려는 장치예요.', '여기서0은 검사 정보의 값이에요. shadow0을 읽으면 준비된 상태로 해석하지만 실제 데이터가0으로 바뀐 것은 아니에요. 검사 대상 값과 검사표 값은 서로 다른 공간에 있어요.', '이 대체 배열은 이미 선언된 저장 공간이에요. 호출할 때마다 새 페이지를 할당하지 않아요. 크기도 한정돼 있으므로 너무 큰 접근을 이 공간으로 돌렸다고 저절로 안전해지는 것은 아니에요. 다음 수업에서 getter의 크기 경고와 분기를 확인해요.'], [('한 dummy 요청에서 반환한 shadow와 origin은 선택한 같은 페이지를 가리키나요?', ['아니요. 각각 새 페이지를 항상 할당해요', '네. 같은 경로의 두 반환 포인터는 같은 dummy페이지예요'], '정답은 두 번째예요. load경로는 둘 다L,store경로는 둘 다S예요. 단,L과S 자체는 다른 페이지라는 점을 구별하세요.'), ('dummy store에 쓰면 dummy load의 상태도 바뀌나요?', ['아니요. 서로 다른 페이지라 그 쓰기가 읽기 공간을 바꾸지 않아요', '네. 언제나 같은 배열이에요'], '정답은 첫 번째예요. 두 배열을 분리한 목적이 읽기 검사 상태를 쓰기로 오염시키지 않는 것이에요. 실제 데이터 내용 변화와도 별개예요.')]), 'os1747': ('주소 안내원이 실제 검사표를 찾거나 대체 표를 알려 줘요. 요청 크기가 너무 크다고 경고하는 것과 그 크기를 작게 고치는 것은 다른 일이에요.', 'getter의 검사 순서와 대체 경로 및 크기 경고의 한계를 이해합니다.', '크기경고→비활성면dummy→활성이면shadow조회→없으면dummy·있으면실제쌍의 순서를 그리세요.', ['getter는 원하는 정보의 위치를 얻는 함수예요. kmsan_get_shadow_origin_ptr는 실제 데이터 주소와 길이를 받아shadow·origin 포인터 쌍을 돌려줘요. 쓰기인지 읽기인지에 따라 대체 페이지도 고를 수 있어요.', '맨 먼저 size>PAGE_SIZE인지 KMSAN_WARN_ON으로 확인해요. 비활성 여부보다 먼저예요. 따라서 KMSAN이 꺼져 있다는 이유만으로 이 크기 경고 조건까지 건너뛴다고 읽으면 안 돼요.', '이 줄은 경고이지 size=PAGE_SIZE 같은 대입이 아니에요. clamp는 큰 값을 한도 안으로 줄이는 일인데 여기에는 그런 조정이 없어요. 경고 처리가 정상적으로 돌아오면 본문의 다음 단계로 진행해요. 실제 경고 정책이 실행을 멈출 수도 있으므로 항상 계속된다고 보장하지는 않아요.', '다음에 kmsan_enabled가 거짓이면 return_dummy로 가요. 참이면 메타데이터 연속성을 확인하고 shadow를 조회해요. shadow가 없으면 역시return_dummy로 가요. 활성화됐다고 모든 주소가 추적되는 것은 아니에요.', 'shadow가 있으면 그 포인터를 ret.shadow에 넣고 origin을 조회하여 ret.origin에 넣어 반환해요. 없는 shadow를 새로 할당하는 코드가 아니에요. 조회,대체 주소 선택,실제 저장 공간 생성은 서로 다른 역할이에요.', 'dummy도 한 페이지 크기예요. 너무 큰 길이를 그대로 가지고 나중에 접근하면 범위를 넘을 수 있다고 원문이 설명해요. 포인터가 반환됐다는 사실만으로 요청 길이가 안전해졌다고 생각하면 안 돼요. 호출자는 정상 접근 크기와 필요한 메타데이터 조건을 지켜야 해요.'], [('size가PAGE_SIZE보다 크면 이 getter가 길이를 자동으로 줄이나요?', ['네. 항상PAGE_SIZE로 바꿔요', '아니요. 경고 조건만 있고 길이를 줄이는 코드는 없어요'], '정답은 두 번째예요. 경고에서 돌아오면 다음 코드로 이어지지만 size를 고치지 않아요. 따라서 포인터 반환을 큰 접근의 안전성 보장으로 해석하면 안 돼요.'), ('활성 상태여도 shadow조회 결과가NULL이면 무엇을 반환하나요?', ['dummy검사 정보 포인터 쌍이에요', '실제 origin페이지를 반드시 새로 할당해요'], '정답은 첫 번째예요. if(!shadow) goto return_dummy예요. 추적 정보가 없는 경우를 위한 경로이며 할당을 수행하는 분기가 아니에요.')]), 'os1748': ('두 건물의 같은 호수를 찾는다고 해 봐요. 첫 건물 입구에서9칸 떨어진 위치라면 다른 건물 입구에서도9칸을 더해 대응 위치를 구해요.', '영역 시작에서 구한 offset을 검사 정보 영역 시작에 더하는 변환을 이해합니다.', '데이터시작1000·주소1009·shadow시작5000이라 놓고1009-1000=9,5000+9=5009를 계산하세요.', ['vmalloc_meta는 가상 주소가vmalloc 또는module 영역에 있을 때 대응 검사 정보 주소를 계산해요. offset은 영역 시작에서 얼마나 떨어졌는지를 나타내요. 실제 주소와offset은 같은 값이 아니에요.', 'vmalloc주소라면 off=addr64-VMALLOC_START예요. 예시로 데이터영역 시작1000,주소1009라면 off는9예요. 그9를shadow영역 시작5000에 더하면5009가 돼요. 이 숫자는 원리를 위한 모형이며 실제 커널 주소가 아니에요.', 'is_origin이 참이면origin영역 시작을,거짓이면shadow영역 시작을 더해요. module주소에서는 MODULES_VADDR를 빼고module용origin·shadow 시작값을 사용해요. 두 종류의 원본 영역과 두 종류의 검사 정보 영역을 구별해서 골라요.', '어느 범위에도 속하지 않으면0을 반환해요. 이 함수는 숫자로 주소를 변환하는 일이며 그 결과 위치에 메모리를 새로 할당하는 동작은 아니에요. 주소 계산만으로 실제 매핑의 모든 조건이 검증됐다고 말할 수는 없어요.', 'origin은4바이트 단위와 관련돼서 직접vmalloc_meta에 미정렬origin주소를 넣으면 경고 조건이 있어요. 이 함수 본문은 주소를 자동으로 아래 경계에 맞추지 않아요. 경고와 정렬 변환은 다른 일이고 경고 뒤 계속 실행되는지도 오류 정책에 달려 있어요.', '일반 kmsan_get_metadata는 origin일 때 먼저ALIGN_DOWN을 해요.4바이트 경계에 맞는영역시작1000의+9주소1009는1008로 내려가offset8이 돼요. shadow조회는offset9를 유지해요. 정렬은 앞단getter에서,영역이동 계산은vmalloc_meta에서 한다고 나눠 읽으세요.'], [('vmalloc주소의offset은 무엇을 빼서 구하나요?', ['항상0을 빼요', 'VMALLOC_START를 빼요'], '정답은 두 번째예요. 현재 주소에서 원본영역 시작을 빼야 그 영역 안의 상대 위치가 나와요. 같은offset을 검사 정보영역 시작에 더하는 방식이에요.'), ('vmalloc_meta에 직접 미정렬origin주소를 주면 조용히 자동정렬하나요?', ['아니요. 이 함수에는 경고가 있고 정렬은 일반getter의 앞단에서 해요', '네. 이 함수 안에서 무조건아래로 정렬해요'], '정답은 첫 번째예요. vmalloc_meta는IS_ALIGNED로 조건을 확인해요. 실제ALIGN_DOWN 대입은kmsan_get_metadata에 있으므로 두 함수의 역할을 혼동하지 마세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_432.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
